+/// Caches the most recent `(target_ts -> block)` answer for one binary-search call site.
+///
+/// Safe to reuse as a lower bound for a *larger or equal* `target_ts`: block timestamps
+/// are monotonic in block number, so the answer for an earlier target can only be at or
+/// below the answer for a later one. Reusing it for an *earlier* target would not be
+/// safe, which is why [`AnswerCache::seed`] refuses in that case.
+///
+/// Stored as a ratchet ([`AnswerCache::update`] only overwrites when the new `target_ts`
+/// is at or after the cached one) because `is_epoch_finalized` is called concurrently
+/// for different, not-necessarily-ordered epochs from claim.rs / challenge.rs /
+/// validate_claim.rs, so updates can arrive out of order.
+struct AnswerCache(std::sync::Mutex<(u64, u64)>);
+
+impl AnswerCache {
+    const fn new() -> Self {
+        Self(std::sync::Mutex::new((0, 0)))
+    }
+
+    /// A provable lower bound for `target_ts`, or 0 when nothing cached is provably
+    /// at or below it. Never returns a block that could sit above the true answer.
+    fn seed(&self, target_ts: u64) -> u64 {
+        let (cached_ts, cached_block) = match self.0.lock() {
+            Ok(guard) => *guard,
+            // A poisoned lock only means some other caller panicked mid-update; the
+            // worst case for correctness is falling back to a full search.
+            Err(poisoned) => *poisoned.into_inner(),
+        };
+        if cached_ts != 0 && cached_ts <= target_ts {
+            cached_block
+        } else {
+            0
+        }
+    }
+
+    fn update(&self, target_ts: u64, block: u64) {
+        let mut guard = match self.0.lock() {
+            Ok(guard) => guard,
+            Err(poisoned) => poisoned.into_inner(),
+        };
+        if target_ts >= guard.0 {
+            *guard = (target_ts, block);
+        }
+    }
+}
+
+/// Per-provider, not per-route: both routes clone the same Arbitrum provider, and the
+/// L1 provider is shared across routes, so one static per call site is exact.
+static L2_EPOCH_END_CACHE: AnswerCache = AnswerCache::new();
+static L1_BATCH_SCAN_CACHE: AnswerCache = AnswerCache::new();
+
+/// The finalized head is a valid lower bound only while its own timestamp is at or
+/// before `target_ts`. Once the chain has finalized past the target, the finalized
+/// block sits *above* the answer and must not be used as `lo` — returning 0 (full
+/// search) is the only safe fallback there.
+const fn finalized_floor(finalized_ts: u64, finalized_block: u64, target_ts: u64) -> u64 {
+    if finalized_ts <= target_ts {
+        finalized_block
+    } else {
+        0
+    }
+}
+
+/// A provable lower bound (`<=` the true answer) for a binary search targeting
+/// `target_ts`: the cached previous answer when it is usable, otherwise the finalized
+/// head when it is provably behind the target, otherwise 0.
+async fn seed_lower_bound(
+    provider: &DynProvider<Ethereum>,
+    cache: &AnswerCache,
+    target_ts: u64,
+) -> u64 {
+    let cached = cache.seed(target_ts);
+    if cached > 0 {
+        return cached;
+    }
+    match provider.get_block_by_number(BlockNumberOrTag::Finalized).await {
+        Ok(Some(block)) => finalized_floor(block.header.timestamp, block.header.number, target_ts),
+        _ => 0,
+    }
+}
