94	pub async fn is_epoch_finalized(
95	    epoch: u64,
96	    epoch_period: u64,
97	    arb_provider: &DynProvider<Ethereum>,
98	    l1_provider: &DynProvider<Ethereum>,
99	    sequencer_inbox: Option<Address>,
100	) -> Result<bool, Box<dyn std::error::Error + Send + Sync>> {
101	    let sequencer_inbox = match sequencer_inbox {
102	        Some(addr) => addr,
103	        None => return Ok(true),
104	    };
105	
106	    let epoch_end_ts = (epoch + 1) * epoch_period;
107	    let l2_lo = seed_lower_bound(arb_provider, &L2_EPOCH_END_CACHE, epoch_end_ts).await;
108	    let l2_block = find_block_by_timestamp_from(arb_provider, epoch_end_ts, l2_lo).await;
109	    L2_EPOCH_END_CACHE.update(epoch_end_ts, l2_block);
110	
111	    let batch = get_batch_for_block(arb_provider, l2_block).await?;
112	
113	    let l1_block = get_l1_block_for_batch(l1_provider, sequencer_inbox, batch, epoch_end_ts).await?;
114	    if l1_block.is_none() {
115	        return Ok(false);
116	    }
117	    let l1_block = l1_block.unwrap();
118	
119	    let finalized = l1_provider.get_block_by_number(BlockNumberOrTag::Finalized).await?;
120	    match finalized {
121	        Some(block) => Ok(block.header.number >= l1_block),
122	        None => Ok(false),
123	    }
124	}
