135	async fn get_l1_block_for_batch(
136	    l1_provider: &DynProvider<Ethereum>,
137	    sequencer_inbox: Address,
138	    batch: u64,
139	    epoch_end_ts: u64,
140	) -> Result<Option<u64>, Box<dyn std::error::Error + Send + Sync>> {
141	    let event_sig = alloy::primitives::keccak256("SequencerBatchDelivered(uint256,bytes32,bytes32,bytes32,uint256,(uint64,uint64,uint64,uint64),uint8)");
142	
143	    let latest = l1_provider.get_block_number().await?;
144	    let l1_lo = seed_lower_bound(l1_provider, &L1_BATCH_SCAN_CACHE, epoch_end_ts).await;
145	    let start_block = find_block_by_timestamp_from(l1_provider, epoch_end_ts, l1_lo).await;
146	    L1_BATCH_SCAN_CACHE.update(epoch_end_ts, start_block);
147	    let mut from_block = start_block;
148	    let mut iterations = 0;
149	
150	    while from_block < latest && iterations < MAX_SEARCH_ITERATIONS {
151	        let to_block = (from_block + SEARCH_RANGE_BLOCKS).min(latest);
152	
153	        let filter = Filter::new()
154	            .address(sequencer_inbox)
155	            .event_signature(event_sig)
156	            .topic1(U256::from(batch))
157	            .from_block(from_block)
158	            .to_block(to_block);
159	
160	        let logs = l1_provider.get_logs(&filter).await?;
161	
162	        if !logs.is_empty() {
163	            return Ok(logs[0].block_number);
164	        }
165	
166	        from_block = to_block + 1;
167	        iterations += 1;
168	    }
169	
170	    Ok(None)
171	}
