130	/// Like [`find_block_by_timestamp`], but seeds the search at `lo` rather than block 0.
131	///
132	/// The indexer's target only moves forward, so its previous answer is a valid lower
133	/// bound. Searching the whole chain each time costs ~28 block fetches on Arbitrum,
134	/// multiplied by the active transport count, every idle cycle, per chain, per route —
135	/// to rediscover a block already known. Seeding cuts that to the log of one cycle's
136	/// worth of blocks.
137	///
138	/// A stale `lo` above the true answer is safe: the search then returns `lo` itself,
139	/// which the caller has already scanned past, so no blocks are skipped.
140	pub async fn find_block_by_timestamp_from(
141	    provider: &DynProvider<Ethereum>,
142	    target_ts: u64,
143	    lo: u64,
144	) -> u64 {
145	    let latest = get_block_with_retry(provider, Default::default()).await;
146	    let latest_num = latest.header.number;
147	
148	    if target_ts >= latest.header.timestamp {
149	        return latest_num;
150	    }
151	
152	    let mut lo = lo.min(latest_num);
153	    let mut hi = latest_num;
154	
155	    while lo < hi {
156	        let mid = lo + (hi - lo) / 2;
157	        let block = get_block_with_retry(provider, mid.into()).await;
158	        if block.header.timestamp < target_ts {
159	            lo = mid + 1;
160	        } else {
161	            hi = mid;
162	        }
163	    }
164	    lo
165	}
