mod tests {
    use super::sync_lower_bound;

    #[test]
    fn sync_lower_bound_uses_a_block_before_the_cutoff() {
        // The normal restart: the stored block is older than the new lookback window,
        // so the first block at or after the cutoff is provably above it.
        assert_eq!(sync_lower_bound(900, 100, 200), 900);
        assert_eq!(sync_lower_bound(900, 199, 200), 900);
    }

    #[test]
    fn sync_lower_bound_refuses_a_block_at_or_after_the_cutoff() {
        // At the cutoff exactly: on a chain with repeated timestamps this block may be
        // a later duplicate of that second, i.e. above the first block at the cutoff.
        assert_eq!(sync_lower_bound(900, 200, 200), 0);
        // Past the cutoff: plainly above the answer.
        assert_eq!(sync_lower_bound(900, 300, 200), 0);
    }

    #[test]
    fn sync_lower_bound_is_zero_for_block_zero() {
        // Block 0 below the cutoff is indistinguishable from "no seed", which is fine:
        // both search the whole chain.
        assert_eq!(sync_lower_bound(0, 100, 200), 0);
    }
}

